#!/usr/bin/env python3
"""Groq JSONL Chat Request Generator and Validator

Offline-first utility for generating and validating JSONL chat requests
before they are sent to Groq. Reads a workspace folder, combines template
with per-job overrides, normalizes messages, and writes output.jsonl + report.json.
"""

import json
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


def load_json(path: Path) -> Dict[str, Any]:
    """Load a JSON file."""
    with path.open('r', encoding='utf-8') as f:
        return json.load(f)


def load_jsonl(path: Path) -> List[Dict[str, Any]]:
    """Load a JSONL file, returning list of parsed objects."""
    jobs = []
    with path.open('r', encoding='utf-8') as f:
        for line_num, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
                jobs.append(obj)
            except json.JSONDecodeError as e:
                raise ValueError(f"Malformed JSON at line {line_num}: {e}")
    return jobs


def validate_job(job: Dict[str, Any], line_num: int) -> None:
    """Validate a job definition. Raises ValueError on malformed jobs."""
    if not isinstance(job, dict):
        raise ValueError(f"Job at line {line_num} is not an object")

    if 'job_id' not in job:
        raise ValueError(f"Job at line {line_num} missing required 'job_id' field")

    if not isinstance(job.get('job_id'), str) or not job['job_id'].strip():
        raise ValueError(f"Job at line {line_num} has invalid 'job_id'")

    if 'messages' not in job:
        raise ValueError(f"Job at line {line_num} missing required 'messages' field")

    if not isinstance(job['messages'], list):
        raise ValueError(f"Job at line {line_num}: 'messages' must be an array")

    for i, msg in enumerate(job['messages']):
        if not isinstance(msg, dict):
            raise ValueError(f"Job {job['job_id']} at line {line_num}: message {i} is not an object")
        if 'role' not in msg:
            raise ValueError(f"Job {job['job_id']} at line {line_num}: message {i} missing 'role'")
        if 'content' not in msg:
            raise ValueError(f"Job {job['job_id']} at line {line_num}: message {i} missing 'content'")


def normalize_content(content: str) -> str:
    """Normalize message content by trimming whitespace."""
    if isinstance(content, str):
        return content.strip()
    return str(content)


def normalize_messages(messages: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Normalize all messages in a conversation."""
    normalized = []
    for msg in messages:
        normalized.append({
            'role': msg['role'].strip() if isinstance(msg['role'], str) else msg['role'],
            'content': normalize_content(msg['content'])
        })
    return normalized


def merge_template_with_job(template: Dict[str, Any], job: Dict[str, Any]) -> Dict[str, Any]:
    """Merge template settings with job-specific overrides."""
    result = {
        'model': template.get('model', 'llama-3.1-8b-instant'),
        'temperature': template.get('temperature', 0.7),
        'max_tokens': template.get('max_tokens', 1024),
        'messages': []
    }

    # Start with template messages
    template_messages = template.get('messages', [])
    result['messages'] = normalize_messages(template_messages)

    # Apply job overrides for scalar fields
    if 'model' in job:
        result['model'] = job['model']
    if 'temperature' in job:
        result['temperature'] = job['temperature']
    if 'max_tokens' in job:
        result['max_tokens'] = job['max_tokens']

    # Job messages replace template messages (job-specific conversation)
    if 'messages' in job:
        result['messages'] = normalize_messages(job['messages'])

    return result


def process_workspace(workspace_path: Path) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Process the entire workspace and return outputs and report."""
    template_path = workspace_path / 'template.json'
    jobs_path = workspace_path / 'jobs.jsonl'

    if not template_path.exists():
        raise FileNotFoundError(f"Template not found: {template_path}")
    if not jobs_path.exists():
        raise FileNotFoundError(f"Jobs file not found: {jobs_path}")

    template = load_json(template_path)
    jobs = load_jsonl(jobs_path)

    # Validate all jobs first
    for line_num, job in enumerate(jobs, 1):
        validate_job(job, line_num)

    # Process each job
    outputs = []
    report = {
        'total_jobs': len(jobs),
        'successful': 0,
        'failed': 0,
        'jobs': []
    }

    for line_num, job in enumerate(jobs, 1):
        job_id = job['job_id']
        try:
            merged = merge_template_with_job(template, job)
            merged['job_id'] = job_id
            outputs.append(merged)
            report['successful'] += 1
            report['jobs'].append({
                'job_id': job_id,
                'status': 'ok',
                'message_count': len(merged['messages'])
            })
        except Exception as e:
            report['failed'] += 1
            report['jobs'].append({
                'job_id': job_id,
                'status': 'error',
                'error': str(e)
            })

    return outputs, report


def write_output_jsonl(outputs: List[Dict[str, Any]], path: Path) -> None:
    """Write outputs to JSONL file."""
    with path.open('w', encoding='utf-8') as f:
        for obj in outputs:
            f.write(json.dumps(obj, ensure_ascii=False) + '\n')


def write_report_json(report: Dict[str, Any], path: Path) -> None:
    """Write report to JSON file (compact)."""
    with path.open('w', encoding='utf-8') as f:
        json.dump(report, f, separators=(',', ':'))


def main():
    """Main entry point."""
    # Default to current directory as workspace
    workspace = Path('.')

    # Allow overriding workspace path via command line
    if len(sys.argv) > 1:
        workspace = Path(sys.argv[1])

    if not workspace.is_dir():
        print(f"Error: Workspace path is not a directory: {workspace}", file=sys.stderr)
        sys.exit(1)

    try:
        outputs, report = process_workspace(workspace)

        # Write outputs
